INSERT INTO `products` VALUES (1,5,'Custom Jersey Printing','custom-jersey-printing','<p>Jersey printing custom berkualitas tinggi. Nyaman dipakai untuk sehari-hari maupun berolahraga.</p>',160000.00,120000.00,NULL,NULL,1,1,'2026-05-28 06:49:17','2026-05-28 06:49:17'),(2,2,'Jersey Futsal & Soccer','jersey-futsal-soccer','<p>Jersey futsal dan soccer seri pro. Bahan menyerap keringat dan sangat ringan.</p>',160000.00,136000.00,NULL,NULL,1,1,'2026-05-28 06:49:44','2026-05-28 06:49:44'),(3,3,'Jersey Esports Pro','jersey-esports-pro','<p>Jersey tim esports khusus didesain untuk kenyamanan gaming maraton Anda.</p>',200000.00,150000.00,NULL,NULL,1,1,'2026-05-28 06:49:44','2026-05-28 06:49:44'),(4,4,'Cycling Jersey Elite','cycling-jersey-elite','<p>Jersey sepeda elit aero fit untuk meningkatkan performa bersepeda Anda ke tingkat selanjutnya.</p>',240000.00,180000.00,NULL,NULL,1,1,'2026-05-28 06:49:44','2026-05-28 06:49:44'),(5,5,'Casual Sport Tee','casual-sport-tee','<p>Kaos olahraga kasual bergaya streetwear.</p>',100000.00,NULL,NULL,NULL,1,1,'2026-05-28 06:49:44','2026-05-28 06:49:44'),(6,6,'Team Training Bibs','team-training-bibs','<p>Rompi latihan untuk tim.</p>',45000.00,NULL,NULL,NULL,1,1,'2026-05-28 06:49:44','2026-05-28 06:49:44');
/*!40000 ALTER TABLE `products` ENABLE KEYS */;
