INSERT INTO `reviews` VALUES (1,'Rakas Dimas','Kapten Garuda Futsal','Jersey dari AMERYGO benar-benar luar biasa! Detail warna printing sangat tajam dan bahannya adem. Bakal langganan terus nih buat tim kita.',5.0,1,'2026-05-28 05:43:56','2026-05-28 05:50:52'),(2,'Bima Anugrah','Manajer SSB Tunas','Pelayanan CS sangat ramah dan sabar merevisi desain. Jahitannya rapi dan ukurannya pas semua. Pengiriman juga sangat cepat dan aman.',5.0,1,'2026-05-28 05:43:56','2026-05-28 05:43:56'),(3,'Deni Ramdani','Corporate Sports Team','Kualitas logo 3D-nya gila sih, mewah banget kelihatannya! Untuk harga segini, kualitas yang didapat jauh di atas ekspektasi.',4.5,1,'2026-05-28 05:43:56','2026-05-28 05:43:56'),(4,'Siska Indah','Kapten Voli Putri','Sempat ragu pesan online tapi ternyata pengerjaannya presisi. Warna merah mudanya keluar banget sesuai desain asli! Puas banget!',5.0,1,'2026-05-28 05:43:56','2026-05-28 05:43:56');
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
UNLOCK TABLES;

