INSERT INTO `settings` VALUES (1,'header_logo','storage/logos/logo_1779978608.png','2026-05-27 17:32:16','2026-05-28 07:30:08'),(2,'header_cta_text','Order Now','2026-05-27 17:32:16','2026-05-27 17:32:16'),(3,'header_cta_url','#','2026-05-27 17:32:16','2026-05-27 17:32:16'),(4,'header_cta_new_tab','0','2026-05-27 17:32:16','2026-05-27 17:32:16'),(5,'footer_description','Produsen pakaian olahraga custom premium terpercaya di Indonesia. Berkomitmen menghadirkan jersey kualitas terbaik untuk mendukung performa maksimal tim Anda di lapangan.','2026-05-27 18:39:26','2026-05-27 18:39:26'),(6,'footer_menu_1_title','Produk Kami','2026-05-27 18:39:26','2026-05-27 18:39:26'),(7,'footer_menu_2_title','Informasi','2026-05-27 18:39:26','2026-05-27 18:39:26'),(8,'footer_contact_title','Hubungi Kami','2026-05-27 18:39:26','2026-05-27 18:39:26'),(9,'hero_title','Custom Jersey &amp;<br/><span style=\"color: #ff6600; text-shadow: 0 0 15px rgba(255,102,0,0.5);\">Sportwear</span><br/>Premium','2026-05-28 05:41:56','2026-05-28 05:43:32'),(10,'hero_description','Desain gratis tanpa batas. Produksi cepat dengan hasil presisi. Jadikan tim Anda tampil layaknya profesional di lapangan.','2026-05-28 05:41:56','2026-05-28 05:41:56'),(11,'hero_btn1_text','Konsultasi','2026-05-28 05:41:56','2026-05-28 05:41:56'),(12,'hero_btn1_url','#','2026-05-28 05:41:56','2026-05-28 05:41:56'),(13,'hero_btn2_text','Lihat Produk','2026-05-28 05:41:56','2026-05-28 05:41:56'),(14,'hero_btn2_url','/products','2026-05-28 05:41:56','2026-05-28 05:41:56'),(15,'hero_badge1','Free Design','2026-05-28 05:41:56','2026-05-28 05:41:56'),(16,'hero_badge2','Fast Production','2026-05-28 05:41:56','2026-05-28 05:41:56'),(17,'hero_image','https://lh3.googleusercontent.com/aida-public/AB6AXuA60XIoVKXCdU4ymRxeQ3a3mbYM2PNRQp5BMF5IdMgbKWcCeQXowbmxZUeWv1yzKe2IlnXadCT3-jpOEqjJcZO7JfNrDh1Cr_DSg-6n5dw9qlu8m6JmmxabcPNp4P3XTYMlZr3yelOXBuikoWe3IbbyL05_tpiKDlALSeIo6RpQCEgpMv_oftrq-UmZeukCv4emNeY-boxww50Cq1D5L687_OlMpyclPAkR8QNBZiwVKt9yMq7M6HPeG2V1ZhYOyNJqsRNTcXwXa77_','2026-05-28 05:41:56','2026-05-28 05:41:56'),(18,'about_title','Kualitas Manufaktur <span style=\"color: #ff6600;\">Terbaik</span>','2026-05-28 05:52:42','2026-05-28 05:52:42'),(19,'about_description','AMERYGO berdedikasi untuk memberikan hasil produksi pakaian olahraga dengan standar tertinggi. Kami menggunakan teknologi printing sublimasi terbaru untuk warna yang tajam dan tidak pudar. Material kain yang kami pilih menjamin kenyamanan maksimal saat beraktivitas berat, didukung dengan jahitan profesional yang kuat dan rapi.','2026-05-28 05:52:42','2026-05-28 05:52:42'),(20,'about_stat1_value','5000+','2026-05-28 05:52:42','2026-05-28 05:52:42'),(21,'about_stat1_label','Jersey Diproduksi','2026-05-28 05:52:42','2026-05-28 05:52:42'),(22,'about_stat2_value','1200+','2026-05-28 05:52:42','2026-05-28 05:52:42'),(23,'about_stat2_label','Klien','2026-05-28 05:52:42','2026-05-28 05:52:42'),(24,'about_stat3_value','150+','2026-05-28 05:52:42','2026-05-28 05:52:42'),(25,'about_stat3_label','Komunitas','2026-05-28 05:52:42','2026-05-28 05:52:42'),(26,'about_stat4_value','5','2026-05-28 05:52:42','2026-05-28 05:52:42'),(27,'about_stat4_label','Tahun Pengalaman','2026-05-28 05:52:42','2026-05-28 05:52:42'),(28,'how_to_order_title','Cara <span style=\"color: #ff6600;\">Pemesanan</span>','2026-05-28 05:58:38','2026-05-28 05:58:38'),(29,'how_to_order_description','Proses pemesanan yang mudah, transparan, dan cepat.','2026-05-28 05:58:38','2026-05-28 05:58:38'),(30,'seo_title','Premium Custom Sportswear & Jersey Printing','2026-05-28 06:11:40','2026-05-28 06:11:40'),(31,'seo_description','AMERYGO Sport adalah produsen pembuatan jersey custom, pakaian olahraga, dan sportswear premium di Indonesia. Melayani pembuatan jersey bola, futsal, basket, sepeda, dan lari dengan bahan premium dan desain custom eksklusif.','2026-05-28 06:11:40','2026-05-28 06:11:40'),(32,'seo_keywords','jersey custom, pembuatan jersey, vendor jersey, bikin jersey bola, jersey futsal, jersey basket, jersey sepeda, jersey running, konveksi baju olahraga, sportswear premium indonesia, amerygo sport','2026-05-28 06:11:40','2026-05-28 06:11:40'),(33,'site_name','AMERYGO','2026-05-28 07:21:26','2026-05-28 07:21:26'),(34,'whatsapp_number','6281234567890','2026-05-28 07:21:26','2026-05-28 07:21:26'),(35,'site_logo_light','uploads/settings/1779978086_site_logo_light.svg','2026-05-28 07:21:26','2026-05-28 07:21:26'),(36,'site_logo_dark','uploads/settings/1779978382_site_logo_dark.svg','2026-05-28 07:26:22','2026-05-28 07:26:22'),(37,'site_logo_sm_dark','uploads/settings/1779978418_site_logo_sm_dark.svg','2026-05-28 07:26:58','2026-05-28 07:26:58'),(38,'site_logo_sm_light','uploads/settings/1779978435_site_logo_sm_light.svg','2026-05-28 07:27:15','2026-05-28 07:27:15'),(39,'site_favicon','uploads/settings/1779978573_favicon.svg','2026-05-28 07:29:33','2026-05-28 07:29:33'),(40,'footer_logo','storage/logos/footer_logo_1779978627.png','2026-05-28 07:30:27','2026-05-28 07:30:27'),(41,'limit_designs','20','2026-06-30 04:59:26','2026-06-30 04:59:26');
